class Solution {
    private int m, n;
    private int[][] score;
    private int[] memo;

    public int maxCompatibilitySum(int[][] students, int[][] mentors) {
        m = students.length;
        n = students[0].length;
        score = new int[m][m];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int s = 0;
                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) s++;
                }
                score[i][j] = s;
            }
        }
        int size = 1 << m;
        memo = new int[size];
        for (int i = 0; i < size; i++) memo[i] = -1;
        return dfs(0);
    }

    private int dfs(int mask) {
        if (mask == (1 << m) - 1) return 0;
        if (memo[mask] != -1) return memo[mask];
        int studentIdx = Integer.bitCount(mask);
        int best = 0;
        for (int j = 0; j < m; j++) {
            if ((mask & (1 << j)) == 0) {
                int cur = score[studentIdx][j] + dfs(mask | (1 << j));
                if (cur > best) best = cur;
            }
        }
        memo[mask] = best;
        return best;
    }
}

